import bcrypt from 'bcrypt';

const SALT_ROUNDS = 10;

app.post('/signup', async (req, res, next) => {
  try {
    const { email, password } = req.body;

    if (!email || !password || password.length < 8) {
      return res.status(400).json({
        success: false,
        error: 'A valid email and a password of at least 8 characters are required'
      });
    }

    const existingUser = await usersCollection.findOne({ email });
    if (existingUser) {
      return res.status(400).json({ success: false, error: 'Email already in use' });
    }

    const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);

    const result = await usersCollection.insertOne({ email, password: hashedPassword });
    res.status(201).json({ success: true, data: { id: result.insertedId, email } });
    // Note: the response NEVER includes the password, hashed or otherwise
  } catch (err) {
    next(err);
  }
});

app.post('/login', async (req, res, next) => {
  try {
    const { email, password } = req.body;

    const user = await usersCollection.findOne({ email });
    if (!user) {
      return res.status(401).json({ success: false, error: 'Invalid credentials' });
    }

    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res.status(401).json({ success: false, error: 'Invalid credentials' });
    }

    res.json({ success: true, data: { id: user._id, email: user.email } });
    // Token/session issuance is added in lessons 4-5
  } catch (err) {
    next(err);
  }
});

