sections.content:
JWT-based protected-route middleware:

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.userId = decoded.userId; // attach verified identity for downstream handlers
    next();
  } catch (err) {
    return res.status(401).json({ success: false, error: 'Invalid or expired token' });
  }
}

Session-based protected-route middleware:

function requireAuth(req, res, next) {
  if (!req.session.userId) {
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }
  req.userId = req.session.userId; // normalizes access the same way as the JWT version above
  next();
}

Applying either version identically across multiple routes:

app.get('/account', requireAuth, accountHandler);
app.post('/posts', requireAuth, createPostHandler);
app.delete('/posts/:id', requireAuth, requireOwnership, deletePostHandler);

