import jwt from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET;

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }

  try {
    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    return res.status(401).json({ success: false, error: 'Invalid or expired token' });
  }
}

async function requireOwnership(req, res, next) {
  const post = await postsCollection.findOne({ _id: new ObjectId(req.params.id) });
  if (!post) return res.status(404).json({ success: false, error: 'Post not found' });
  if (post.authorId.toString() !== req.userId) {
    return res.status(403).json({ success: false, error: 'You do not own this post' });
  }
  req.post = post;
  next();
}

// Authenticated only - any logged-in user can view their own account
app.get('/account', requireAuth, async (req, res, next) => {
  try {
    const user = await usersCollection.findOne({ _id: new ObjectId(req.userId) });
    res.json({ success: true, data: { email: user.email } });
  } catch (err) { next(err); }
});

// Authenticated only - any logged-in user can create a post
app.post('/posts', requireAuth, async (req, res, next) => {
  try {
    const newPost = { title: req.body.title, authorId: new ObjectId(req.userId) };
    const result = await postsCollection.insertOne(newPost);
    res.status(201).json({ success: true, data: { _id: result.insertedId, ...newPost } });
  } catch (err) { next(err); }
});

// Authenticated AND authorized - only the post's actual owner can delete it
app.delete('/posts/:id', requireAuth, requireOwnership, async (req, res, next) => {
  try {
    await postsCollection.deleteOne({ _id: req.post._id });
    res.status(204).send();
  } catch (err) { next(err); }
});

