import jwt from 'jsonwebtoken';
import { ObjectId } from 'mongodb';
const JWT_SECRET = process.env.JWT_SECRET;

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }
  try {
    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    return res.status(401).json({ success: false, error: 'Invalid or expired token' });
  }
}

async function requireCommentOwnership(req, res, next) {
  const comment = await commentsCollection.findOne({ _id: new ObjectId(req.params.id) });
  if (!comment) return res.status(404).json({ success: false, error: 'Comment not found' });
  if (comment.authorId.toString() !== req.userId) {
    return res.status(403).json({ success: false, error: 'You do not own this comment' });
  }
  req.comment = comment;
  next();
}

app.get('/profile', requireAuth, async (req, res, next) => {
  try {
    const user = await usersCollection.findOne({ _id: new ObjectId(req.userId) });
    res.json({ success: true, data: { email: user.email } });
  } catch (err) { next(err); }
});

app.post('/comments', requireAuth, async (req, res, next) => {
  try {
    const newComment = { text: req.body.text, authorId: new ObjectId(req.userId) };
    const result = await commentsCollection.insertOne(newComment);
    res.status(201).json({ success: true, data: { _id: result.insertedId, ...newComment } });
  } catch (err) { next(err); }
});

app.delete('/comments/:id', requireAuth, requireCommentOwnership, async (req, res, next) => {
  try {
    await commentsCollection.deleteOne({ _id: req.comment._id });
    res.status(204).send();
  } catch (err) { next(err); }
});

