// A simplified authentication helper module (not a full React component,
// to focus on the request/response flow itself)

let currentToken = null; // in-memory storage - see lesson 10 for tradeoffs

async function signup(email, password, username) {
  const response = await fetch('/signup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password, username })
  });
  if (!response.ok) {
    const data = await response.json();
    throw new Error(data.error || 'Signup failed');
  }
  return response.json();
}

async function login(email, password) {
  const response = await fetch('/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  if (!response.ok) {
    const data = await response.json();
    throw new Error(data.error || 'Login failed');
  }
  const data = await response.json();
  currentToken = data.data.token; // store the token for subsequent requests
  return data;
}

async function fetchProtectedResource(path) {
  const response = await fetch(path, {
    headers: { Authorization: `Bearer ${currentToken}` }
  });

  if (response.status === 401) {
    currentToken = null; // credential is no longer valid - clear it
    throw new Error('Session expired - please log in again');
  }

  if (!response.ok) {
    throw new Error('Request failed');
  }

  return response.json();
}

function logout() {
  currentToken = null; // for JWTs, client-side discarding is the primary mechanism
}

