    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password, username })
  });
  if (!response.ok) {
    const data = await response.json();
    throw new Error(data.error || 'Signup failed');
  }
  return response.json();
}

async function login(email, password) {
  const response = await fetch('/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include', // ensures the session cookie is stored
    body: JSON.stringify({ email, password })
  });
  if (!response.ok) {
    const data = await response.json();
    throw new Error(data.error || 'Login failed');
  }
  return response.json();
}

async function fetchProtectedResource(path) {
  const response = await fetch(path, {
    credentials: 'include' // ensures the session cookie is sent automatically
  });

  if (response.status === 401) {
    throw new Error('Session expired - please log in again');
  }
  if (!response.ok) {
    throw new Error('Request failed');
  }
  return response.json();
}

async function logout() {
  await fetch('/logout', { method: 'POST', credentials: 'include' });
  // unlike JWTs, the session is destroyed server-side; there's no
  // client-side token to discard, since none was ever manually stored
}

