// ORIGINAL CODE BEING REVIEWED:
app.post('/reset-password', async (req, res) => {
  const { email, newPassword } = req.body;
  await usersCollection.updateOne(
    { email },
    { $set: { password: newPassword } } // stored directly, no hashing!
  );
  res.json({ success: true });
});

// AUDIT AGAINST THE 5 CHECKS:
// 1. Trust boundary: SEVERE FAILURE - anyone who knows ANY user's email
//    can reset that user's password with no verification of identity
//    at all. There's no check that the requester actually IS that user
//    (no reset token, no current-password confirmation, nothing).
// 2. Irreversibility: FAILS - newPassword is stored directly via $set,
//    completely bypassing bcrypt hashing entirely.
// 3. Mechanism choice: N/A for this specific feature, but related -
//    a real reset flow needs its OWN short-lived, single-use token
//    (a deliberate design decision, not covered by login's existing JWT).
// 4. Layered defense: FAILS - no rate limiting on an endpoint that could
//    otherwise be used to repeatedly attempt resetting arbitrary accounts.
// 5. Complete-flow testing: clearly never tested adversarially - simply
//    trying this with someone else's real email immediately reveals
//    the severe trust boundary failure in check 1.

// CORRECTED VERSION (conceptual - full reset-token implementation is
// beyond this module's scope, but the structure should reflect):
// - require a previously-issued, short-lived, single-use reset token
//   (sent via email, verified via signature/expiration, similar to a JWT)
// - hash newPassword with bcrypt before storing it
// - rate-limit reset attempts
// - never reveal whether a given email exists in the system, exactly
//   echoing lesson 3's email-enumeration prevention

