// AUDIT:
// 1. Trust boundary: SEVERE FAILURE - userId is taken directly from the
//    request body, letting any attacker change ANY user's email simply by
//    supplying a different userId, with no verification of who is actually
//    making the request.
// 2. Irreversibility: N/A for this specific route, no password involved.
// 3. Mechanism choice: N/A directly, but identity should come from a
//    verified token/session (req.userId), not the request body.
// 4. Layered defense: FAILS - no rate limiting on a sensitive
//    account-modifying action.
// 5. Complete-flow testing: clearly never tested adversarially - supplying
//    a different userId immediately reveals the severe trust boundary gap.

// CORRECTED VERSION:
app.post('/change-email', requireAuth, async (req, res, next) => {
  try {
    const { newEmail } = req.body;

    if (!newEmail || typeof newEmail !== 'string') {
      return res.status(400).json({ success: false, error: 'A valid newEmail is required' });
    }

    const result = await usersCollection.updateOne(
      { _id: new ObjectId(req.userId) }, // identity from verified middleware, never the body
      { $set: { email: newEmail } }
    );

    if (result.matchedCount === 0) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    res.json({ success: true, data: { email: newEmail } });
  } catch (err) {
    next(err);
  }
});
